buildBindings(input){const host=document.getElementById('bind-list');if(!host)return;host.innerHTML='';for(const[name,label]of Object.entries(this.bindingNames)){const row=document.createElement('div');row.className='bind-row';const text=document.createElement('span');text.textContent=label;const button=document.createElement('button');button.textContent=this.formatBind(this.settings.data.binds[name]);button.addEventListener('click',()=>{document.querySelectorAll('.bind-row button').forEach(x=>x.classList.remove('waiting'));button.classList.add('waiting');button.textContent='PRESS KEY';const handler=e=>{e.preventDefault();input.setBind(name,e.code);button.textContent=this.formatBind(e.code);button.classList.remove('waiting');window.removeEventListener('keydown',handler);this.settings.save()};window.addEventListener('keydown',handler,{once:false})});row.append(text,button);host.appendChild(row)}}
