updateBuyUI(){this.ui.setMoney(this.money);const el=document.getElementById('buy-grid');if(!el)return;for(const b of el.querySelectorAll('.buy-item')){const id=b.dataset.id,d=WEAPONS[id];b.classList.toggle('selected',id===this.pendingPrimary);b.disabled=!!(d.price>this.money&&id!==this.weapons.order[0])}}
