buildBuyMenu(){if(this._buyBuilt)return;this._buyBuilt=true;const grid=document.getElementById('buy-grid'),ids=['service-pistol','heavy-pistol','burst-pistol','compact-smg','fast-smg','suppressed-smg','assault-rifle','heavy-rifle','burst-rifle','pump-shotgun','auto-shotgun','bolt-sniper','semi-sniper','light-machine'];grid.innerHTML='';for(const id of ids){const d=WEAPONS[id],b=document.createElement('button');b.className='buy-item';b.dataset.id=id;b.innerHTML='<b>'+d.name+'</b><span>'+d.type.toUpperCase()+' · '+d.damage+' DMG · '+d.mag+' MAG</span><small>$'+d.price+'</small>';b.addEventListener('click',()=>{if(d.price>this.money&&id!==this.weapons.order[0]){this.ui.center('NOT ENOUGH MONEY',700);return}this.pendingPrimary=id;this.updateBuyUI();this.audio.ui()});grid.appendChild(b)}document.getElementById('buy-done').addEventListener('click',()=>this.commitBuyAndClose())}
